INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63551416', 63551416, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan BMHP Skrining Profil Lipid Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 152655925000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda; Menyediakan BMHP Skrining Profil Lipid berupa Strip POCT Lipid Panel, Lancet , dan Alcohol Swab', 'Spesifikasi BMHP Skrining Profil Lipid sebagai berikut : 1. Strip POCT Lipid Panel POCT Lipid Panel dapat mengukur komponen lipid darah yaitu; Kolesterol total, Trigliserida, HDL. Waktu pengukuran sampel sekitar ± 3 menit Volume sampel 10 – 50 µL Standar CV < 10%; Akurasi tidak melebihi ± 15% Rentang pengukuran : Kolesterol total : 100 – 500 mg/dL Trigliserida: 45 – 650 mg/dL HDL : 15 – 120 mg/dL Strip dapat disimpan pada suhu ± 2 – 30oC Expired date/ tanggal kadaluwarsa minimal 18 bulan saat diterima di Dinkes Kab/Kota. Produk diutamakan TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan. Strip POCT harus kompatibel dengan alat. Pembelian strip POCT dengan jumlah Kabupaten/Kota sekaligus mendapatkan alat yang kompatible sejumlah puskesmas di masing-masing Kabupaten/Kota. 2. Lancet : Jarum penusuk steril sekali pakai untuk pengambilan sampel darah kapiler dari jari tangan dan akan terkunci setelah digunakan Kedalamam penetrasi ± 1,6 mm Diameter jarum ± 0,36 mm Kemasan isi 100 pcs Masa kadaluawarsa minimal 2 tahun. Produk memiliki TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan. 3. Kapas Alkohol Bahan dasar: Non woven/katun mengandung alkohol 70%. Hanya untuk pemakaian luar dan sekali pakai. Kemasan: Box, Satuan terbungkus dengan aluminium foil Suhu penyimpanan: maksimal 30 derajat celcius (suhu ruang). Expired date/ tanggal kadaluwarsa minimal 18 bulan saat diterima di Dinkes Kab/Kota. Produk memiliki TKDN/Produk Dalam Negeri dan memiliki izin edar yang diterbitkan oleh Kementerian Kesehatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1025386);
